WITH gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) > INTERVAL '14' DAY THEN 1 ELSE 0 END AS is_new_session FROM sessions), islands AS (SELECT id, customer_id, started_at, SUM(is_new_session) OVER (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT CASE WHEN island_id >= 6 THEN 'PREMIUM' ELSE 'STANDARD' END AS island_id_tier, customer_id, ROUND(AVG(island_id), 2) AS avg_island_id, APPROX_PERCENTILE(island_id, ARRAY(0.25, 0.5, 0.75)) AS island_id_quartiles, COUNT(DISTINCT id) AS distinct_ids FROM islands GROUP BY ROLLUP (CASE WHEN island_id >= 6 THEN 'PREMIUM' ELSE 'STANDARD' END, customer_id) HAVING distinct_ids > 1;
